import {getRuleDefinitions} from '../utils/messages'
import {clickOn, findAllEl, findEl, isClicked, markAsClicked, printLine, sleep} from './modules'

printLine('Must reload extension for modifications to take effect.')

var isScrollingScriptStarted = false

// task Auto review and collapse autogenerated files
async function onLoad() {
  const rules = await getRuleDefinitions()
  if (!rules.autoCollapseRule?.enabled) return
  if (isScrollingScriptStarted) return
  if (!location.href.match(/https:\/\/github.com/)) return

  isScrollingScriptStarted = true

  printLine('Page Tuner automation is running...')

  rules.autoCollapseRule.specifics.autoGenerateFileNames.forEach((fileName: string) => {
    const withins = findAllEl(`//div[div[h3/a/code[text()[contains(.,'${fileName}')]]]]`)
    for (const within of withins) {
      if (!within) continue
      if (isClicked(within as HTMLElement)) continue

      const expandButton = findEl(
        `div/button[svg[contains(@class,"octicon-chevron")]]`,
        within
      ) as HTMLButtonElement | null

      const reviewedCheckbox = findEl(
        'div/div/button[@aria-label="Not Viewed" or @aria-label="Viewed"]',
        within
      ) as HTMLButtonElement | null

      const slug = findEl(`div/h3/a/code[text()[contains(.,'${fileName}')]]`, within)?.textContent || ''

      if (reviewedCheckbox && reviewedCheckbox.getAttribute('aria-pressed') === 'true') {
        markAsClicked(reviewedCheckbox, slug)
        markAsClicked(within as HTMLElement, slug)
      } else if (reviewedCheckbox && reviewedCheckbox.getAttribute('aria-pressed') === 'false') {
        clickOn(reviewedCheckbox, slug)
        markAsClicked(within as HTMLElement, slug)
      } else {
        clickOn(expandButton, slug)
        markAsClicked(within as HTMLElement, slug)
      }
    }
  })

  isScrollingScriptStarted = false
}

if (location.href.match(/https:\/\/github.com/)) {
  const mainLayout = document.querySelector('div[class*="PageLayout-Content"]')
  if (mainLayout) {
    const observer = new MutationObserver(onLoad)
    observer.observe(mainLayout, {childList: true, subtree: true, characterData: true, attributes: true})
  } else {
    printLine('Could not find div[class*="PageLayout-Content"]')
  }
}

async function exposeCompareAndOpenPullRequestButtons() {
  const rules = await getRuleDefinitions()
  if (!rules.moveCompareButtonRule?.enabled) return
  if (!location.href.match(/https:\/\/github.com/)) return

  // Expose Compare and Open pull request buttons in branch summary
  await sleep(150)

  const branchInfoBar = document.querySelector('[data-testid="branch-info-bar"]')

  const contributeButton = findEl('//button[span/span[text()[contains(.,"Contribute")]]]') as HTMLButtonElement | null

  contributeButton?.click()

  // TODO: for unknown reason elements are findable after some time.
  await sleep(20)

  const compareButtons = findEl('//div[a/span/span[text()[contains(.,"Open pull request")]]] ')

  compareButtons && contributeButton?.parentElement?.appendChild(compareButtons)

  contributeButton?.click()

  contributeButton && (contributeButton.style.display = 'none')
}

exposeCompareAndOpenPullRequestButtons()

